// Floating language toggle for the Health & Wellness landing.
// Owner order 2026-10-16: «فقط یک دکمه FA روی قسمت انگلیسی بزار و روی فارسی
// یک دکمه EN که بین هم لینک شده باشند» — graphics must stay untouched.
//
// Mechanism: the two route handlers splice ONE self-contained element (a
// <style> block + a single <a>) right before `</body>`. Nothing else in the
// served HTML changes a single byte — landing-en.ts / landing-fa.ts stay
// frozen exactly as generated by scripts/build-health-landing.mjs.
//
// The pill reuses the landing's own :root custom properties (--card, --line,
// --tx, --b) so it visually blends with the existing dark design, floats
// (position:fixed) so it cannot reflow/shift any existing element, and is
// mirrored per direction: bottom-right on EN (LTR), bottom-left on FA (RTL).
export function langToggle(opts: {
  label: 'FA' | 'EN';
  href: string;
  ariaLabel: string;
  side: 'left' | 'right';
}): string {
  const pos = opts.side; // physical side; FA page mirrors to 'left'
  return (
    '<style>#lang-fab{position:fixed;' +
    pos +
    ':16px;bottom:calc(16px + env(safe-area-inset-bottom,0px));z-index:50;display:inline-flex;align-items:center;justify-content:center;height:44px;padding:0 18px;border-radius:999px;border:1px solid var(--line,rgba(255,255,255,.1));background:var(--card,rgba(255,255,255,.05));color:var(--tx,#eef1ff)!important;font:600 13px/1 \'Space Grotesk\',Inter,sans-serif;letter-spacing:.12em;text-decoration:none!important;backdrop-filter:blur(10px);-webkit-backdrop-filter:blur(10px);transition:background .2s ease,border-color .2s ease,transform .2s ease}#lang-fab:hover{background:rgba(255,255,255,.12);border-color:rgba(255,255,255,.25);transform:translateY(-1px)}#lang-fab:focus-visible{outline:2px solid var(--b,#19e3c1);outline-offset:2px}</style>' +
    '<a id="lang-fab" href="' +
    opts.href +
    '" aria-label="' +
    opts.ariaLabel +
    '" title="' +
    opts.ariaLabel +
    '">' +
    opts.label +
    '</a>'
  );
}
